#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ISMAY 認証機能(API-AUTH + UI-01ログイン画面)適用パッチ（一度きり実行・プロジェクトルート直下）
====================================================================
OIDC準拠(Firebase非依存)の認証実装一式(register/login/mfa/refresh/logout/sessions API
+ /register /login /dashboard 画面)をサーバーへ適用し、依存パッケージ導入・
Prisma再生成・TypeScriptコンパイルチェックを行い、すべて成功した場合のみ
GitHubへ自動pushする。

実行方法:
    cd ~/projects/ismay
    python3 apply_ismay_auth_v1.py

失敗した場合は該当ステップで停止し、pushは一切行わない。
成功した場合、本スクリプト自身を自動削除する。
"""
import subprocess
import sys
import os
import json
import base64
import secrets

REPO_ROOT = os.path.dirname(os.path.abspath(__file__))
APP_DIR = os.path.join(REPO_ROOT, "app")
ENV_PATH = os.path.join(APP_DIR, ".env")

FILES_B64 = json.loads(r'''{"src/lib/db.ts": "", "src/lib/auth/password.ts": "", "src/lib/auth/totp.ts": "", "src/lib/auth/tokens.ts": "", "src/lib/auth/response.ts": "", "src/lib/auth/session.ts": "", "src/lib/auth/cookies.ts": "", "src/lib/auth/guard.ts": "", "src/lib/auth/client.ts": "", "src/app/api/v1/auth/register/route.ts": "", "src/app/api/v1/auth/login/route.ts": "", "src/app/api/v1/auth/mfa/verify/route.ts": "", "src/app/api/v1/auth/mfa/enroll/route.ts": "", "src/app/api/v1/auth/mfa/enroll/confirm/route.ts": "", "src/app/api/v1/auth/refresh/route.ts": "", "src/app/api/v1/auth/logout/route.ts": "", "src/app/api/v1/auth/sessions/route.ts": "", "src/app/api/v1/auth/sessions/[id]/route.ts": "", "src/app/api/v1/auth/me/route.ts": "", "src/components/auth/LoginForm.tsx": "", "src/components/auth/RegisterForm.tsx": "", "src/components/auth/DashboardClient.tsx": "", "src/app/register/page.tsx": "aW1wb3J0IHsgUmVnaXN0ZXJGb3JtIH0gZnJvbSAiQC9jb21wb25lbnRzL2F1dGgvUmVnaXN0ZXJGb3JtIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIFJlZ2lzdGVyUGFnZSgpIHsKICByZXR1cm4gPFJlZ2lzdGVyRm9ybSAvPjsKfQo=", "src/app/login/page.tsx": "aW1wb3J0IHsgTG9naW5Gb3JtIH0gZnJvbSAiQC9jb21wb25lbnRzL2F1dGgvTG9naW5Gb3JtIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIExvZ2luUGFnZSgpIHsKICByZXR1cm4gPExvZ2luRm9ybSAvPjsKfQo=", "src/app/dashboard/page.tsx": "aW1wb3J0IHsgRGFzaGJvYXJkQ2xpZW50IH0gZnJvbSAiQC9jb21wb25lbnRzL2F1dGgvRGFzaGJvYXJkQ2xpZW50IjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIERhc2hib2FyZFBhZ2UoKSB7CiAgcmV0dXJuIDxEYXNoYm9hcmRDbGllbnQgLz47Cn0K"}''')

NEW_DEPS = ["hash-wasm@^4.12.0", "otplib@^13.4.1", "qrcode@^1.5.4", "jose@^6.2.9"]
NEW_DEV_DEPS = ["@types/qrcode@^1.5.6"]


def run(cmd, cwd):
    print("\n$ " + " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd)
    return result.returncode


def fail(message):
    print("\n[FAIL] " + message)
    print("       pushは行いません。書き込み済みファイルはそのまま残ります(git checkoutで戻せます)。")
    sys.exit(1)


def write_files():
    print("[1/6] 認証実装ファイル一式を書き込み (" + str(len(FILES_B64)) + "件)")
    for rel_path, b64content in FILES_B64.items():
        abs_path = os.path.join(APP_DIR, rel_path)
        os.makedirs(os.path.dirname(abs_path), exist_ok=True)
        with open(abs_path, "wb") as f:
            f.write(base64.b64decode(b64content))
        print("  - app/" + rel_path)


def ensure_env_secrets():
    print("[2/6] .env の秘密鍵(AUTH_JWT_SECRET / MFA_ENCRYPTION_KEY)を確認")
    current = ""
    if os.path.isfile(ENV_PATH):
        with open(ENV_PATH, encoding="utf-8") as f:
            current = f.read()

    additions = []
    if "AUTH_JWT_SECRET" not in current:
        secret = base64.b64encode(secrets.token_bytes(48)).decode("ascii")
        additions.append("AUTH_JWT_SECRET=" + secret)
        print("  - AUTH_JWT_SECRET を新規生成して追加します")
    else:
        print("  - AUTH_JWT_SECRET は既に設定済み(変更しません)")

    if "MFA_ENCRYPTION_KEY" not in current:
        key = base64.b64encode(secrets.token_bytes(32)).decode("ascii")
        additions.append("MFA_ENCRYPTION_KEY=" + key)
        print("  - MFA_ENCRYPTION_KEY を新規生成して追加します")
    else:
        print("  - MFA_ENCRYPTION_KEY は既に設定済み(変更しません)")

    if additions:
        with open(ENV_PATH, "a", encoding="utf-8") as f:
            f.write("\n# --- 認証機能(apply_ismay_auth_v1.py により自動生成) ---\n")
            for line in additions:
                f.write(line + "\n")


def main():
    if not os.path.isdir(APP_DIR):
        fail("app ディレクトリが見つかりません: " + APP_DIR)

    write_files()
    ensure_env_secrets()

    print("[3/6] npm install (認証関連の新規依存パッケージ)")
    if run(["npm", "install", "--save"] + NEW_DEPS, cwd=APP_DIR) != 0:
        fail("npm installでエラーが検出されました(依存パッケージ)。")
    if run(["npm", "install", "--save-dev"] + NEW_DEV_DEPS, cwd=APP_DIR) != 0:
        fail("npm installでエラーが検出されました(開発用依存パッケージ)。")

    print("[4/6] npx prisma generate")
    if run(["npx", "prisma", "generate"], cwd=APP_DIR) != 0:
        fail("prisma generateでエラーが検出されました。")

    print("[5/6] npx tsc --noEmit (コンパイルエラー0件ゲート)")
    if run(["npx", "tsc", "--noEmit"], cwd=APP_DIR) != 0:
        fail("TypeScriptコンパイルエラーが検出されました。")

    print("[6/6] コンパイルエラー0件を確認。GitHubへpushします。")
    run(["git", "add", "-A"], cwd=REPO_ROOT)
    commit_msg = "feat(auth): OIDC準拠の認証API(register/login/mfa/refresh/logout/sessions)+UI-01ログイン画面を追加"
    if run(["git", "commit", "-m", commit_msg], cwd=REPO_ROOT) != 0:
        print("[WARN] コミットする変更がないか、コミットに失敗しました。git statusを確認してください。")
        sys.exit(1)
    if run(["git", "push", "origin", "main"], cwd=REPO_ROOT) != 0:
        fail("git pushに失敗しました。手動で `git push origin main` を実行してください。")

    print("\n[CLEANUP] 本スクリプト自身を削除します")
    os.remove(os.path.abspath(__file__))

    print("\n完了しました。次の手順:")
    print("  1. npm run dev")
    print("  2. ブラウザで http://192.168.1.11:13000/register を開きアカウント登録")
    print("  3. http://192.168.1.11:13000/login でログイン")
    print("  4. /dashboard でMFA(TOTP)設定・Google Authenticator等でQRスキャンして動作確認")


if __name__ == "__main__":
    main()
